      render(<ChipBar statuses={defaultStatuses} />);
      expect(screen.getByRole('button', { name: /all/i })).toBeInTheDocument();
    });

    it('all chips start unpressed', () => {
      render(<ChipBar statuses={defaultStatuses} />);
      for (const status of defaultStatuses) {
        expect(screen.getByRole('button', { name: status })).toHaveAttribute('aria-pressed', 'false');
      }
    });

    it('All chip starts unpressed', () => {
      render(<ChipBar statuses={defaultStatuses} />);
      expect(screen.getByRole('button', { name: /all/i })).toHaveAttribute('aria-pressed', 'false');
    });
  });

  describe('individual chip toggle', () => {
    it('pressing an unpressed chip sets aria-pressed to true', async () => {
      const user = userEvent.setup();
      render(<ChipBar statuses={defaultStatuses} />);
      const chip = screen.getByRole('button', { name: 'Open' });
      await user.click(chip);
      expect(chip).toHaveAttribute('aria-pressed', 'true');
    });

    it('pressing a pressed chip sets aria-pressed to false', async () => {
      const user = userEvent.setup();
      render(<ChipBar statuses={defaultStatuses} />);
      const chip = screen.getByRole('button', { name: 'Open' });
      await user.click(chip);
      await user.click(chip);
      expect(chip).toHaveAttribute('aria-pressed', 'false');
