      render(<ChipBar statuses={defaultStatuses} />);
      await user.click(screen.getByRole('button', { name: 'Open' }));
      expect(screen.getByRole('button', { name: 'In Progress' })).toHaveAttribute('aria-pressed', 'false');
      expect(screen.getByRole('button', { name: 'Closed' })).toHaveAttribute('aria-pressed', 'false');
    });
  });

  describe('multi-select', () => {
    it('multiple chips can be pressed simultaneously', async () => {
      const user = userEvent.setup();
      render(<ChipBar statuses={defaultStatuses} />);
